<?php
 require_once('utilsTrait.php'); trait med_cisz_organizationTrait { use med_cisz_utilsTrait; private function createOrganization(): void { $ciszData = getSessionValue('cisz'); self::storeLinkUnique( $this->db, 'Enterprise', $ciszData->organization_id, $this->settings->organizationId, ); if (!empty($ciszData->department_ids)) { if (count($ciszData->department_ids) > 1) { $organizationId = $ciszData->department_ids[1]; } else { $organizationId = $ciszData->department_ids[0]; } } else { $organizationId = $ciszData->organization_id; } $this->organization = (object) [ 'link' => (object) [ 'reference' => 'Organization/' . $organizationId, ], 'id' => $organizationId ]; } }